<script setup lang="ts">
import {computed,onMounted,onUnmounted,reactive,ref} from 'vue';
import {newLiquify,LIQUIFY_TOOLS} from '../../../packages/comp-bridge/liquify.mjs';
import {parityMessages} from './parity-labels';
import type{Language}from'./types';
const props=defineProps<{language:Language;source:{width:number;height:number;data:Uint8ClampedArray};saved?:any}>();
const emit=defineEmits(['close','apply']);
const t=computed(()=>parityMessages[props.language]),settings=reactive({...newLiquify(props.source.width,props.source.height),...props.saved}),canvas=ref<HTMLCanvasElement>(),busy=ref(true),error=ref(''),canUndo=ref(false),canRedo=ref(false),original=ref(false),working=ref(false),showsFrozen=ref(true);
let worker:Worker,stroke=false,inFlight=false,ending=false,queued:any,frame=0,downPoint:number[]|undefined,stationaryTimer:ReturnType<typeof setInterval>|undefined;
const plain=()=>Object.fromEntries(['diameter','hardness','strength','rate','fixedEdges','keepsAlpha','usesPressure','reversesDirection','tool'].map(key=>[key,(settings as any)[key]]));
function send(action:string){if(!worker)return;if(action==='save')busy.value=true;worker.postMessage({action,settings:plain()});}
function draw(image:any){const target=canvas.value;if(!target)return;target.width=image.width;target.height=image.height;target.getContext('2d')!.putImageData(new ImageData(image.data,image.width,image.height),0,0);}
function toggleFrozen(){worker.postMessage({action:'overlay',show:showsFrozen.value});}
function showOriginal(){if(original.value)draw(props.source);else send('end');}
function position(event:PointerEvent){const bounds=canvas.value!.getBoundingClientRect();return[(event.clientX-bounds.left)/bounds.width*props.source.width,(event.clientY-bounds.top)/bounds.height*props.source.height,event.pointerType==='pen'?event.pressure:1];}
function flush(){frame=0;if(inFlight||busy.value)return;if(queued){const point=queued;queued=undefined;inFlight=true;worker.postMessage({action:'stroke',point,settings:plain()});}else if(ending){ending=false;inFlight=true;send('end');}}
function start(event:PointerEvent){if(busy.value||original.value||event.button!==0)return;stroke=true;working.value=true;canvas.value!.setPointerCapture(event.pointerId);downPoint=position(event);queued=downPoint;flush();stationaryTimer=setInterval(()=>{if(stroke&&settings.tool!=='Forward Warp'&&!busy.value){queued=downPoint;flush();}},75);}
function move(event:PointerEvent){if(!stroke)return;downPoint=position(event);queued=downPoint;if(!frame)frame=requestAnimationFrame(flush);}
function end(){if(!stroke)return;stroke=false;ending=true;clearInterval(stationaryTimer);flush();}
onMounted(()=>{worker=new Worker(new URL('./liquify-worker.ts',import.meta.url),{type:'module'});worker.onmessage=event=>{inFlight=false;if(event.data.error){error.value=t.value.failed;busy.value=false;return;}if(event.data.saved){emit('apply',event.data.saved);return;}if(!original.value)draw(event.data.image);canUndo.value=event.data.canUndo;canRedo.value=event.data.canRedo;busy.value=false;if(queued||ending)flush();else if(!stroke)working.value=false;};worker.onerror=()=>{error.value=t.value.failed;busy.value=false;};worker.postMessage({action:'init',source:props.source,saved:props.saved?JSON.parse(JSON.stringify(props.saved)):undefined});});
onUnmounted(()=>{cancelAnimationFrame(frame);clearInterval(stationaryTimer);worker?.terminate();});
</script>
<template><div class="modal-shade"><section role="dialog" aria-modal="true" :aria-label="t.liquify" class="dialog liquify-dialog" @keydown.esc.stop.prevent="emit('close')"><h2>{{t.liquify}}</h2><p v-if="error" role="alert">{{error}}</p><p>{{t.liquifyTip}}</p><fieldset :disabled="busy||working"><div class="style-fields"><label>{{t.tool}}<select v-model="settings.tool" data-testid="liquify-tool"><option v-for="(tool,index) in LIQUIFY_TOOLS" :key="tool" :value="tool">{{t.liquifyTools[index]}}</option></select></label><label>{{t.diameter}}<input v-model.number="settings.diameter" type="number" min="2" max="3000"></label><label>{{t.hardness}}<input v-model.number="settings.hardness" type="number" min="0" max="1" step=".01"></label><label>{{t.strength}}<input v-model.number="settings.strength" type="number" min=".01" max="1" step=".01"></label><label>{{t.rate}}<input v-model.number="settings.rate" type="number" min=".1" max="3" step=".1"></label></div><div class="button-row"><label><input v-model="settings.fixedEdges" type="checkbox">{{t.fixedEdges}}</label><label><input v-model="settings.keepsAlpha" type="checkbox">{{t.keepAlpha}}</label><label><input v-model="settings.usesPressure" type="checkbox">{{t.pressure}}</label><label><input v-model="settings.reversesDirection" type="checkbox">{{t.reverse}}</label><label><input v-model="showsFrozen" type="checkbox" @change="toggleFrozen">{{t.showFrozen}}</label><label><input v-model="original" type="checkbox" @change="showOriginal">{{t.before}}</label></div></fieldset><canvas ref="canvas" data-testid="liquify-canvas" @pointerdown="start" @pointermove="move" @pointerup="end" @pointercancel="end"></canvas><div class="button-row"><button :disabled="busy||working||!canUndo" @click="send('undo')">{{t.undo}}</button><button :disabled="busy||working||!canRedo" @click="send('redo')">{{t.redo}}</button><button :disabled="busy||working" @click="send('reset')">{{t.reconstructAll}}</button></div><div class="button-row dialog-actions"><button @click="emit('close')">{{t.cancel}}</button><button class="primary" data-testid="apply-liquify" :disabled="busy||working||!!error" @click="send('save')">{{t.apply}}</button></div></section></div></template>
<style scoped>.liquify-dialog{width:min(1000px,95vw);max-height:94vh;overflow:auto}.liquify-dialog canvas{display:block;max-width:100%;max-height:46vh;object-fit:contain;margin:auto;touch-action:none;background:repeating-conic-gradient(#666 0 25%,#888 0 50%) 0/16px 16px}.liquify-dialog fieldset{border:0;padding:0}</style>
